  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM analytics.sales",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count >= 15;
  return {
    passed,
    message: passed ? `Sales table has ${count} rows.` : `Expected >=15 rows, got ${count}.`,
    details: { count },
  };
}

